    @Test
    fun gcm_random_vectors_match_oracle() {
        for (v in randomGcmVectors) {
            val p = v.split("|")
            val key = h(p[0]); val iv = h(p[1]); val aad = h(p[2])
            val pt = h(p[3]); val expect = h(p[4])
            assertContentEquals(expect, Aes256Gcm.seal(key, iv, pt, aad),
              "GCM random vector mismatch vs OpenSSL oracle (GHASH/CTR/tag)")
        }
    }
}
